from worker import Pool

# 2 workers, 12 jobs - check if job 1 survives
for trial in range(5):
    pool = Pool()
    for job in range(12):
        pool.submit(job)
    got = {}
    def worker(wid):
        n = 0
        while True:
            j = pool.claim(wid)
            if j is None:
                got[wid] = n
                return
            n += 1
            pool.handoff(wid, ("r", wid, j))
    ts = [threading.Thread(target=worker, args=(i,)) for i in range(2)]
    for t in ts: t.start()
    for t in ts: t.join(5)
    print(trial, "sum:", sum(got.values()), "queue:", len(pool._queue), "reports:", {k: v[2] for k,v in pool._reports.items()})
